namespace arkostracker
{
RawLinearExporter::RawLinearExporter(const std::shared_ptr<Song>& pSong, ExportConfiguration pExportConfiguration,
                                     std::set<InstrumentType> pInstrumentTypes) noexcept : song(pSong),
                                                                                           exportConfiguration(std::move(pExportConfiguration)),
                                                                                           instrumentTypes(std::move(pInstrumentTypes)),
                                                                                           rstInstrumentId(),
                                                                                           channelWithValidInstrumentType(),
                                                                                           validInstrumentIds()
{
}

std::pair<bool, std::unique_ptr<SongExportResult>> RawLinearExporter::performTask() noexcept
{
    auto exportResult = std::make_unique<SongExportResult>();
    auto success = true;

    // Note that the Song must NOT be optimized, else instruments will not match will the sample export.
    jassert(exportConfiguration.getSubsongIds().size() == 1); // Only one subsong is supported.
    const auto subsongId = exportConfiguration.getFirstSubsongId();

    auto songOutputStream = std::make_unique<juce::MemoryOutputStream>();
    SourceGenerator sourceGenerator(exportConfiguration.getSourceConfiguration(), *songOutputStream);

    const auto songName = song->getTitle();
    sourceGenerator.declareComment((songName.isEmpty() ? "" : (songName + ", ")) + "Linear RAW format V1.0.").addEmptyLine();
    sourceGenerator.declareComment("Generated by Arkos Tracker 3.").addEmptyLine();

    // Org?
    if (exportConfiguration.getAddress().isPresent()) {
        sourceGenerator.declareAddressChange(exportConfiguration.getAddress().getValue()).addEmptyLine();
    }

    const auto baseLabel = getBaseLabel();
    sourceGenerator.declareLabel(baseLabel);
    sourceGenerator.declareExternalLabel(baseLabel).addEmptyLine();

    generateData(subsongId, sourceGenerator);

    sourceGenerator.declareEndOfFile();

    exportResult->setSongStream(std::move(songOutputStream));

    return { success, std::move(exportResult) };
}

juce::String RawLinearExporter::getBaseLabel() const noexcept
{
    return exportConfiguration.getBaseLabel();
}

void RawLinearExporter::generateData(const Id& subsongId, SourceGenerator& sourceGenerator) noexcept
{
    prepare();

    const auto baseLabel = getBaseLabel();
    const auto loopLabel = baseLabel + "loop";
    sourceGenerator.setPrefixForDisark(baseLabel);

    SongPlayer songPlayer(song);
    const auto startLocation = Location(subsongId, 0);
    const auto [_, newPastEndLocation] = song->getLoopStartAndPastEndPositions(subsongId);
    const auto psgCount = song->getPsgCount(subsongId);
    const auto channelCount = PsgValues::getChannelCount(psgCount);

    // As a default, we consider the state OK on all channels. Should work on 99.99% cases.
    for (auto channelIndex = 0; channelIndex < channelCount; ++channelIndex) {
        channelWithValidInstrumentType.insert(channelIndex);
    }

    const auto [counter, upTo, loopToCounter] = FrameCounter::count(*song, subsongId);
    const auto iterationCount = counter;
    jassert(iterationCount > 0);

    songPlayer.play(startLocation, startLocation, newPastEndLocation, true, true);

    auto waitCounter = 0;

    sourceGenerator.declareByteRegionStart();

    for (auto iterationIndex = 0; iterationIndex < iterationCount; ++iterationIndex) {
        for (auto browsedPsgIndex = 0; browsedPsgIndex < psgCount; ++browsedPsgIndex) {
            // Necessary to get all the registers of all the PSGs.
            songPlayer.getNextRegisters(browsedPsgIndex);
        }

        // Loop to encode?
        if (iterationIndex == loopToCounter) {
            // Before encoding the loop label, encodes the possible pending wait.
            encodeWait(sourceGenerator, waitCounter);
            sourceGenerator.declareLabel(loopLabel);
        }

        const auto result = songPlayer.getResultsOffline();

        // Browses each channel.
        auto channelIndex = 0;
        for (const auto& channelResult : result) {
            const auto& cells = channelResult->getCells();
            jassert(cells.size() <= 1);
            const auto isNewNotePlayed = (cells.size() == 1); // If 0, tick > 0.
            auto noteOptional = channelResult->getNewPlayedNote();
            auto instrumentIdOptional = channelResult->getInstrumentId();
            auto areEffectsPresent = channelResult->isEffectDeclared();

            // Is there an instrument?
            // As long as there is no new instrument, we don't encode anything if we already are in an invalid state.
            if (instrumentIdOptional.isAbsent() && (channelWithValidInstrumentType.find(channelIndex) == channelWithValidInstrumentType.cend())) {
                continue;
            }

            auto mustEncodeRst = false;
            auto mustSkip = false;
            if (isNewNotePlayed && instrumentIdOptional.isPresent()) {
                // A new instrument is present. Can we encode what follows?
                if (isInstrumentValid(instrumentIdOptional.getValue())) {
                    channelWithValidInstrumentType.insert(channelIndex);
                } else {
                    const auto eraseCount = channelWithValidInstrumentType.erase(channelIndex);
                    mustEncodeRst = (eraseCount > 0); // No need to encode a RST again if we are still in an illegal state.
                    mustSkip = (eraseCount == 0); // But don't encode this note!
                }
            }

            // Encodes something?
            if (!mustSkip && (mustEncodeRst || noteOptional.isPresent() || areEffectsPresent)) {
                // Before encoding the code, encodes the possible wait.
                encodeWait(sourceGenerator, waitCounter);

                sourceGenerator.declareByte(channelIndex, "Command: data on channel index " + juce::String(channelIndex) + ".");

                if (mustEncodeRst) {
                    noteOptional = CellConstants::rstNote;
                    instrumentIdOptional = rstInstrumentId;
                    areEffectsPresent = false;
                }

                const auto note = noteOptional.isPresent() ? noteOptional.getValue() : absentNoteValue;
                auto instrumentIndex = absentInstrumentValue;
                if (instrumentIdOptional.isPresent() && noteOptional.isPresent()) {
                    // No instrument without a note.
                    const auto foundInstrumentId = song->getInstrumentIndex(instrumentIdOptional.getValue());
                    if (foundInstrumentId.isPresent()) {
                        instrumentIndex = foundInstrumentId.getValue();
                    } else {
                        jassertfalse; // Abnormal.
                    }
                }

                // Encodes the found data.
                sourceGenerator.declareByte(note, "Note (255 if absent).");
                sourceGenerator.declareByte(instrumentIndex, "Instrument (255 if absent).");
                if (areEffectsPresent) {
                    const auto rawEffects = channelResult->getEffects();
                    const auto normalizedCellEffects = CellEffectsChecker::normalize(rawEffects, noteOptional.isPresent(),
                        instrumentIdOptional.isPresent());

                    for (const auto& cellEffect : normalizedCellEffects.getPresentEffects()) {
                        sourceGenerator.declareByte(static_cast<int>(cellEffect.getEffect()), "Effect index.");
                        sourceGenerator.declareWord(cellEffect.getEffectRawValue(), "Effect value.");
                    }
                }
                sourceGenerator.declareByte(endEffect, "End of effects.");
                sourceGenerator.addEmptyLine();
            }

            ++channelIndex;
        }

        ++waitCounter;
    }

    // Before encoding the end, makes sure there are no pending wait.
    encodeWait(sourceGenerator, waitCounter);

    // Encodes the end.
    sourceGenerator.declareByte(dataTypeEnd, "Command: end.");
    sourceGenerator.declareWordForceReference(loopLabel, "Loop here.");

    sourceGenerator.declareByteRegionEnd();
}

void RawLinearExporter::encodeWait(SourceGenerator& sourceGenerator, int& waitCounter) noexcept
{
    if (waitCounter <= 0) {
        return;
    }

    if (waitCounter == 1) {
        sourceGenerator.declareByte(dataTypeEndFrame, "Command: end of frame.");
    } else {
        sourceGenerator.declareByte(dataTypeWait, "Command: wait.");
        sourceGenerator.declareWord(waitCounter);
    }
    sourceGenerator.addEmptyLine();

    waitCounter = 0;
}

void RawLinearExporter::prepare() noexcept
{
    validInstrumentIds.clear();

    song->performOnInstruments([&](const std::vector<std::unique_ptr<Instrument>>& instruments) {
        auto instrumentIndex = 0;
        for (const auto& instrument : instruments) {
            // Instrument 0 is always encoded.
            if ((instrumentIndex == 0) || (instrumentTypes.find(instrument->getType()) != instrumentTypes.cend())) {
                validInstrumentIds.insert(instrument->getId());

                if (instrumentIndex == 0) {
                    rstInstrumentId = instrument->getId();
                }
            }

            ++instrumentIndex;
        }
    });
}

bool RawLinearExporter::isInstrumentValid(const Id& instrumentId) const noexcept
{
    return (validInstrumentIds.find(instrumentId) != validInstrumentIds.cend());
}
} // namespace arkostracker
